pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        c.initialize();
        vm.prank(actor);
        bool ok;
        try c.transferOwnership(actor) {} catch {}
        try c.renounceOwnership() {} catch {}
        assertTrue(c.owner() == address(0));
    }
}
